-- Successful exchange case studies.
--
-- Kept separate from dead_exchanges and mid_exchanges because success is an
-- outcome class, not a verdict that can be represented honestly in either
-- existing table. `metric_type` is deliberately first-class: spot volume,
-- aggregator-routed volume, and perpetual notional overlap or measure different
-- activity and must never be summed or ranked as if they were interchangeable.
--
-- Research snapshot: 2026-07-29. The richer, reviewable source material lives
-- in docs/dex-success-cohort-2026-07-29.json. The self-contained JSON payload
-- below is expanded by SQLite at migration time; it avoids duplicated SQL while
-- preserving a clean-database replay path.

CREATE TABLE IF NOT EXISTS successful_exchanges (
  slug            TEXT NOT NULL,
  type            TEXT NOT NULL CHECK (type IN ('dex', 'cex')),
  venue_type      TEXT NOT NULL,
  name            TEXT NOT NULL,
  launched        TEXT,
  primary_chain   TEXT,
  status          TEXT NOT NULL,
  metric_label    TEXT NOT NULL,
  metric_type     TEXT NOT NULL,
  metric_unit     TEXT NOT NULL,
  metric          REAL,
  why_successful  TEXT,
  outlook         TEXT,
  profile         TEXT NOT NULL,
  sources         TEXT NOT NULL,
  updated_at      TEXT DEFAULT (datetime('now')),
  PRIMARY KEY (type, slug),
  CHECK (json_valid(profile)),
  CHECK (json_valid(sources))
);

CREATE INDEX IF NOT EXISTS idx_successful_exchanges_type
  ON successful_exchanges(type);
CREATE INDEX IF NOT EXISTS idx_successful_exchanges_metric_type
  ON successful_exchanges(metric_type);
CREATE INDEX IF NOT EXISTS idx_successful_exchanges_primary_chain
  ON successful_exchanges(primary_chain);

