ORChain daily-volume series","url":"https://api.llama.fi/summary/dexs/thorchain-dex?dataType=dailyVolume"}],"updated_at":"2026-07-29"},{"slug":"uniswap","type":"dex","venue_type":"exchange","name":"Uniswap","launched":"2018-11","primary_chain":"Ethereum","status":"successful_established","metric_label":"24h spot volume","metric_type":"spot_volume_24h","metric_unit":"USD","metric":2158254170,"why_successful":"Uniswap created durable, permissionless liquidity infrastructure and expanded it across versions and chains. Its integrations and developer surface make the protocol a liquidity primitive, not only a destination interface.","outlook":"Category leader with growing 90-day volume in the research snapshot; fragmentation across versions and chains and the changing relationship between fees and UNI remain material risks.","profile":{"operational_model":"permissionless multi-chain spot AMM; v2 constant-product, v3 concentrated liquidity, v4 singleton and hooks","chains":["Ethereum","Base","Arbitrum","Polygon","OP Mainnet","Unichain","Avalanche","BNB Chain","multiple additional EVM chains"],"token":{"launched":true,"symbol":"UNI","launch_date":"2020-09-16","role":"protocol governance; genesis allocation included a retroactive user and LP distribution","source_url":"https://blog.uniswap.org/uni"},"metrics":{"spot_volume_24h_usd":2158254170,"spot_volume_30d_usd":50767348712,"spot_volume_all_time_usd":3776695155079,"spot_tvl_usd":3066365156,"peak_daily_spot_volume_usd":8232827599,"peak_daily_spot_volume_date":"2025-01-20","as_of":"2026-07-29","source_url":"https://api.llama.fi/summary/dexs/uniswap?dataType=dailyVolume"},"success_factors":["first_mover_amm","permissionless_integrations","multi_chain_distribution","capital_efficiency","developer_platform"],"risks":["fragmented_liquidity","governance_token_value_capture","intense_competition"],"synthesis":"Success preceded UNI by almost two years, so the token was a governance and distribution layer built on demonstrated product-market fit, not the original source of it."},"sources":[{"title":"Introducing UNI","url":"https://blog.uniswap.org/uni"},{"title":"DefiLlama Uniswap daily-volume series","url":"https://api.llama.fi/summary/dexs/uniswap?dataType=dailyVolume"},{"title":"DefiLlama Uniswap protocol TVL","url":"https://defillama.com/protocol/uniswap"}],"updated_at":"2026-07-29"}]')
)
INSERT OR REPLACE INTO successful_exchanges
  (slug, type, venue_type, name, launched, primary_chain, status, metric_label, metric_type, metric_unit, metric, why_successful, outlook, profile, sources, updated_at)
SELECT
  json_extract(value, '$.slug'),
  json_extract(value, '$.type'),
  json_extract(value, '$.venue_type'),
  json_extract(value, '$.name'),
  json_extract(value, '$.launched'),
  json_extract(value, '$.primary_chain'),
  json_extract(value, '$.status'),
  json_extract(value, '$.metric_label'),
  json_extract(value, '$.metric_type'),
  json_extract(value, '$.metric_unit'),
  json_extract(value, '$.metric'),
  json_extract(value, '$.why_successful'),
  json_extract(value, '$.outlook'),
  json_extract(value, '$.profile'),
  json_extract(value, '$.sources'),
  json_extract(value, '$.updated_at')
FROM dossier_seed, json_each(dossier_seed.payload);
